## 2. `/src/scene.js`  
```js
import { MeshStandardMaterial } from 'three';
import { Invader } from './entities/Invader';
import { Projectile } from './entities/Projectile';
import { Player } from './entities/Player';
import { ParticleManager } from '../particle-manager';

export class Scene {
    constructor() {
        this.invaders = [];
        this.projectiles = [];
        this.player = null;
        this.particleMgr = new ParticleManager();
    }

    spawnInvader(position, angle) {
        const invader = new Invader(
            position.x, position.y,
            angle,
            0.5, // radius
            1.2, // speed
            0.8, // health
            0.6, // size
            this.particleMgr
        );
        this.invaders.push(invader);
    }

    spawnProjectile(position, direction) {
        const proj = new Projectile(
            position.x, position.y,
            direction.x, direction.y,
            0, 0, 0,
            1, // speed
            0.3, // size
            this.particleMgr
        );
        this.projectiles.push(proj);
    }

    update(delta, physics) {
        // Update projectiles
        this.projectiles.forEach(p => p.update(delta, physics));
        // Update invaders
        this.invaders.forEach(i => i.update(delta, physics));
        // Remove off-screen or destroyed entities
        this.invaders = this.invaders.filter(i => i.isAlive());
        this.projectiles = this.projectiles.filter(p => p.isAlive());
    }

    addToScene(scene) {
        this.invaders.forEach(i => scene.add(i.mesh));
        this.projectiles.forEach(p => scene.add(p.mesh));
        this.player?.addToScene(scene);
        this.particleMgr.attachToScene(scene);
    }
}
```

