import * as THREE from 'three';
import { SimplexNoise } from '../utils/procedural';

export class Invader {
    constructor(x, y, angle, radius, speed, health, size, particleMgr) {
        this.radius = radius;
        this.speed = speed;
        this.health = health;
        this.size = size;
        this.angle = angle;
        this.position = new THREE.Vector3(x, y, 0).applyQuaternion(
            new THREE.Quaternion().setFromEuler(angle, 0, 0)
        );
        this.mesh = this.createMesh(particleMgr);
        this.velocity = new THREE.Vector3(speed * Math.cos(angle), speed * Math.sin(angle), 0);
        this.particleMgr = particleMgr;
    }

    createMesh(pm) {
        const geometry = new THREE.SphereGeometry(this.radius, 24, 16);
        geometry.scale(this.size, this.size, this.size);
        const mat = new THREE.MeshStandardMaterial({ color: 0xff00, emissive: 0x00ff00, emissivePower: 2.5 });
        const mesh = new THREE.Mesh(geometry, mat);
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        return mesh;
    }

    update(delta, physics) {
        this.position.add(this.velocity.clone().multiplyScalar(delta));
        // Simple AABB collision placeholder
        if (this.position.z > 19) physics.applyGravityOnGround();
    }

    isAlive() { return this.health > 0; }
}
```

