import * as THREE from 'three';

export class Projectile {
    constructor(x, y, vx, vy, size, speed, particleMgr) {
        this.x = x; this.y = y;
        this.vx = vx; this.vy = vy;
        this.size = size;
        this.speed = speed;
        this.mesh = this.createMesh(particleMgr);
        this.velocity = new THREE.Vector3(this.vx, this.vy, 0).normalize().multiplyScalar(speed);
        this.isAlive = true;
    }

    createMesh(pm) {
        const geometry = new THREE.CylinderGeometry(0.03, 0.03, 4, 8);
        const mat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const mesh = new THREE.Mesh(geometry, mat);
        mesh.position.set(this.x, this.y, 0.5);
        return mesh;
    }

    update(delta, physics) {
        this.x += this.vx * delta;
        this.y += this.vy * delta;
        this.mesh.position.set(this.x, this.y, 0.5);
        if (this.x < 0 || this.x > 20 || this.y < -10 || this.y > 10) this.isAlive = false;
    }
    isAlive() { return this.isAlive; }
}
