## 7. `/src/vfx/CameraShake.js`  
```js
export default class CameraShake {
    constructor(physics, composer, intensity, duration) {
        this.physics = physics;
        this.composer = composer;
        this.intensity = intensity;
        this.duration = duration;
        this.startTime = null;
    }
    update(physics, delta) {
        if (!this.startTime) this.startTime = performance.now();
        const elapsed = performance.now() - this.startTime;
        const t = Math.min(elapsed / this.duration, 1);
        const scale = this.intensity * t;
        const shakeMatrix = new THREE.Matrix4().identity();
        shakeMatrix.applyQuaternion(
            new THREE.Quaternion().setFromEuler(
                randomFloat(-0.5, 0.5),
                randomFloat(-0.5, 0.5),
                0
            )
        );
        shakeMatrix.getScale().set(scale, scale, scale);
        this.composer.getRenderTarget().material.matrixAutoUpdate = false;
        this.composer.getRenderTarget().material.matrix = shakeMatrix;
    }
}
```

