```js
export default class ParticleBurst {
    constructor(renderer, scene, pm, count, speed, radius) {
        this.renderer = renderer; this.scene = scene; this.pm = pm;
        this.count = count; this.speed = speed; this.radius = radius;
        this.burst = [];
    }
    spawn(x, y) {
        for (let i=0;i<this.count;i++) {
            const angle = randomFloat(0, 2*Math.PI);
            const r = randomFloat(0, this.radius);
            const pos = new THREE.Vector3(
                x + Math.cos(angle)*r*this.speed,
                y + Math.sin(angle)*r*this.speed,
                0
            );
            const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 1, emissivePower: 3 });
            const p = new THREE.Mesh(
                new THREE.SphereGeometry(0.1, 8, 8),
                mat
            );
            p.position.copy(pos);
            this.burst.push(p);
            this.scene.add(p);
        }
    }
    update(physics) {
        // Simplified: animate scale down
        this.burst.forEach(p => {
            p.scale.setScalar(p.scale.x - 0.01, p.scale.y - 0.01, p.scale.z - 0.01);
            if (p.scale.x < 0.01) this.scene.remove(p, this.burst);
        });
    }
}
```

